from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_transcript_log_flag_values_and_whitespace():
    assert parse_transcript_log([" a , 3 , 1 \n", "b, -2, 0", " c , 4 , \t"]) == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 4, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "#comment", "  # ignored,even,with,commas", "a,1,1"]
    assert parse_transcript_log(iter(lines)) == [{"id": "a", "day": 1, "flagged": True}]
    assert parse_transcript_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# skipped", " \t", "ok,2,0", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    old = {"id": "b", "day": 1, "flagged": True}
    intermediate = {"id": "b", "day": 9, "flagged": True}
    latest = {"id": "b", "day": 2, "flagged": False}
    a = {"id": "a", "day": 2, "flagged": None}
    z = {"id": "z", "day": 0, "flagged": True}
    events = [old, a, intermediate, z, latest]
    assert dedupe_transcripts(events) == [z, a, latest]
    assert events == [old, a, intermediate, z, latest]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_and_range_filtered():
    events = [
        {"day": 4, "flagged": True},
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 6, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 1, 0]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 5, 1) == []


def test_daily_flag_counts_empty_and_negative_days():
    assert daily_flag_counts([], -2, 1) == [0, 0, 0, 0]
    assert daily_flag_counts([{"day": -1, "flagged": True}], -2, 0) == [0, 1, 0]
