from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_summary_pooled_rounded_and_nonempty_groups():
    groups = {
        "small": [{"id": "a", "day": 1, "flagged": True}],
        "large": [
            {"id": "b", "day": 3, "flagged": False},
            {"id": "c", "day": 5, "flagged": None},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 10) == {"rate": 0.333, "recent": 1, "groups": 2}


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 1), (2, 1), (4, 2), (10, 2)])
def test_monitor_summary_recent_uses_calendar_days(days, recent):
    groups = {"g": [{"day": 1, "flagged": True}, {"day": 4, "flagged": True}]}
    assert monitor_summary(groups, days) == {"rate": 1.0, "recent": recent, "groups": 1}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_orders_by_rate_then_name_and_excludes_empty():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "low": [{"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "high": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, 3) == ["high", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["high", "a", "z", "low"]
    assert top_flagged_groups(groups, 0) == []


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_empty(groups):
    assert top_flagged_groups(groups, 3) == []
